        for (int i = 0; i < 10; i++) fs.add(ex.submit(() -> post("/api/orders", Map.of("items", List.of(Map.of("productId", pid, "quantity", 1))), "X-User-Id", "u", "Idempotency-Key", key).getStatusCode().value()));
        Map<Integer, Integer> counts = new TreeMap<>();
        for (Future<Integer> f : fs) counts.merge(f.get(), 1, Integer::sum);
