24	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
25	
26	/** 모든 오류를 RFC 9457 application/problem+json (type,title,status,detail,code) 으로 변환한다. */
27	@RestControllerAdvice
28	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
29	
30	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
31	
32	    @ExceptionHandler(ApiException.class)
33	    public ResponseEntity<Object> handleApi(ApiException ex) {
34	        return problem(ex.code(), ex.getMessage(), null);
35	    }
36	
37	    @ExceptionHandler(ConstraintViolationException.class)
38	    public ResponseEntity<Object> handleConstraintViolation(ConstraintViolationException ex) {
39	        return problem(ErrorCode.VALIDATION_ERROR, ex.getMessage(), null);
40	    }
41	
42	    @ExceptionHandler(Exception.class)
43	    public ResponseEntity<Object> handleUnexpected(Exception ex) {
44	        log.error("Unhandled exception", ex);
45	        return problem(ErrorCode.INTERNAL_ERROR, "Unexpected error.", null);
46	    }
47	
48	    @Override
49	    protected ResponseEntity<Object> handleMethodArgumentNotValid(
50	            MethodArgumentNotValidException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
51	        List<Map<String, String>> errors = new ArrayList<>();
52	        ex.getBindingResult().getAllErrors().forEach(e -> {
53	            Map<String, String> m = new LinkedHashMap<>();
54	            m.put("field", e instanceof FieldError fe ? fe.getField() : e.getObjectName());
55	            m.put("message", e.getDefaultMessage());
56	            errors.add(m);
57	        });
58	        return problem(ErrorCode.VALIDATION_ERROR, "Request validation failed.", errors);
59	    }
60	
61	    @Override
62	    protected ResponseEntity<Object> handleHandlerMethodValidationException(
63	            HandlerMethodValidationException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
64	        List<Map<String, String>> errors = new ArrayList<>();
65	        for (MessageSourceResolvable e : ex.getAllErrors()) {
66	            Map<String, String> m = new LinkedHashMap<>();
67	            m.put("message", e.getDefaultMessage());
68	            errors.add(m);
69	        }
70	        return problem(ErrorCode.VALIDATION_ERROR, "Request validation failed.", errors);
71	    }
72	
73	    @Override
74	    protected ResponseEntity<Object> handleExceptionInternal(
75	            Exception ex, Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
76	        ProblemDetail pd = body instanceof ProblemDetail p ? p : ProblemDetail.forStatus(statusCode);
77	        int value = statusCode.value();
78	        String code = codeFor(value);
79	        if (value == 400) {
80	            pd.setType(URI.create(ErrorCode.VALIDATION_ERROR.typeUri()));
81	            pd.setTitle(ErrorCode.VALIDATION_ERROR.title());
82	        } else if (value >= 500) {
83	            log.error("Server error", ex);
84	            pd.setDetail("Unexpected error.");
85	        } else {
86	            pd.setType(URI.create("https://example.com/problems/" + code.toLowerCase().replace('_', '-')));
87	        }
88	        if (pd.getTitle() == null) {
89	            HttpStatus hs = HttpStatus.resolve(value);
90	            pd.setTitle(hs != null ? hs.getReasonPhrase() : "Error");
91	        }
92	        if (pd.getDetail() == null) {
93	            pd.setDetail(pd.getTitle());
94	        }
95	        pd.setProperty("code", code);
96	        return ResponseEntity.status(statusCode)
97	                .headers(headers)
98	                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
99	                .body(pd);
100	    }
101	
102	    private static String codeFor(int status) {
103	        return switch (status) {
104	            case 400 -> ErrorCode.VALIDATION_ERROR.name();
105	            case 404 -> "NOT_FOUND";
106	            case 405 -> "METHOD_NOT_ALLOWED";
107	            case 406 -> "NOT_ACCEPTABLE";
108	            case 415 -> "UNSUPPORTED_MEDIA_TYPE";
109	            case 500 -> ErrorCode.INTERNAL_ERROR.name();
110	            default -> {
111	                HttpStatus hs = HttpStatus.resolve(status);
112	                yield hs != null ? hs.name() : "ERROR";
113	            }
114	        };
115	    }
116	
117	    private static ResponseEntity<Object> problem(ErrorCode code, String detail, List<Map<String, String>> errors) {
118	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(code.status(), detail);
119	        pd.setType(URI.create(code.typeUri()));
120	        pd.setTitle(code.title());
121	        pd.setProperty("code", code.name());
122	        if (errors != null && !errors.isEmpty()) {
123	            pd.setProperty("errors", errors);
124	        }
125	        return ResponseEntity.status(code.status())
126	                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
127	                .body(pd);
128	    }
129	}
