2	
3	import com.fasterxml.jackson.annotation.JsonIgnore;
4	import jakarta.validation.constraints.AssertTrue;
5	import jakarta.validation.constraints.Min;
6	import jakarta.validation.constraints.NotBlank;
7	import jakarta.validation.constraints.NotNull;
8	import jakarta.validation.constraints.Pattern;
9	import java.time.DateTimeException;
10	import java.time.Instant;
11	import java.time.OffsetDateTime;
12	import java.time.format.DateTimeFormatter;
13	import java.time.temporal.ChronoUnit;
14	
15	/**
16	 * 시각은 문자열로 받아 오프셋 포함 ISO-8601 만 허용한다(숫자 타임스탬프·오프셋 없는 값은 400).
17	 * 금액(value, minOrderAmount, maxDiscountAmount)은 Long — int 초과 허용.
18	 */
19	public record CouponCreateRequest(
20	        @NotBlank @Pattern(regexp = "^[A-Z0-9]{4,20}$") String code,
21	        @NotNull CouponType type,
22	        @NotNull Long value,
23	        @Min(0) Long minOrderAmount,
24	        @Min(1) Long maxDiscountAmount,
25	        @NotNull @Min(1) Integer totalQuantity,
26	        @NotBlank String validFrom,
27	        @NotBlank String validUntil) {
28	
29	    @JsonIgnore
30	    @AssertTrue(message = "value must be >= 1 for FIXED and 1..100 for RATE")
31	    public boolean isValueValidForType() {
32	        if (type == null || value == null) {
33	            return true;
34	        }
35	        return switch (type) {
36	            case FIXED -> value >= 1;
37	            case RATE -> value >= 1 && value <= 100;
38	        };
39	    }
40	
41	    @JsonIgnore
42	    @AssertTrue(message = "validFrom/validUntil must be ISO-8601 with offset and validFrom < validUntil")
43	    public boolean isPeriodValid() {
44	        if (validFrom == null || validUntil == null || validFrom.isBlank() || validUntil.isBlank()) {
45	            return true; // @NotBlank 가 보고한다
46	        }
47	        Instant from = parse(validFrom);
48	        Instant until = parse(validUntil);
49	        return from != null && until != null && from.isBefore(until);
50	    }
51	
52	    public Instant validFromInstant() {
53	        return parse(validFrom);
54	    }
55	
56	    public Instant validUntilInstant() {
57	        return parse(validUntil);
58	    }
59	
60	    static Instant parse(String s) {
61	        try {
62	            OffsetDateTime odt = OffsetDateTime.parse(s, DateTimeFormatter.ISO_OFFSET_DATE_TIME);
63	            int year = odt.toInstant().atOffset(java.time.ZoneOffset.UTC).getYear();
64	            if (year < 1 || year > 9999) {
65	                return null;
66	            }
67	            return odt.toInstant().truncatedTo(ChronoUnit.MICROS);
68	        } catch (DateTimeException e) {
69	            return null;
70	        }
71	    }
72	}
