3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import com.example.order.common.Times;
6	import java.time.Clock;
7	import org.springframework.dao.DataIntegrityViolationException;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	@Service
12	public class CouponService {
13	
14	    private final CouponRepository repository;
15	    private final Clock clock;
16	
17	    public CouponService(CouponRepository repository, Clock clock) {
18	        this.repository = repository;
19	        this.clock = clock;
20	    }
21	
22	    @Transactional
23	    public CouponResponse create(CouponCreateRequest req) {
24	        if (repository.existsByCode(req.code())) {
25	            throw duplicate(req.code());
26	        }
27	        Coupon coupon = new Coupon(req.code(), req.type(), req.value(),
28	                req.minOrderAmount() == null ? 0L : req.minOrderAmount(),
29	                req.maxDiscountAmount(), req.totalQuantity(),
30	                req.validFromInstant(), req.validUntilInstant(), Times.now(clock));
31	        try {
32	            return CouponResponse.from(repository.saveAndFlush(coupon));
33	        } catch (DataIntegrityViolationException e) {
34	            String msg = String.valueOf(e.getMostSpecificCause().getMessage());
35	            if (msg.contains("uk_coupons_code")) {
36	                throw duplicate(req.code());
37	            }
38	            throw e;
39	        }
40	    }
41	
42	    @Transactional(readOnly = true)
43	    public CouponResponse get(String code) {
44	        return repository.findByCode(code)
45	                .map(CouponResponse::from)
46	                .orElseThrow(() -> new ApiException(ErrorCode.COUPON_NOT_FOUND, "Coupon " + code + " not found."));
47	    }
48	
49	    private static ApiException duplicate(String code) {
50	        return new ApiException(ErrorCode.DUPLICATE_COUPON_CODE, "Coupon code " + code + " already exists.");
51	    }
52	}
