12	import com.example.order.product.ProductRepository;
13	import com.fasterxml.jackson.core.JsonProcessingException;
14	import com.fasterxml.jackson.databind.ObjectMapper;
15	import java.time.Clock;
16	import java.time.Instant;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.stream.Collectors;
20	import org.springframework.dao.DataIntegrityViolationException;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	/**
25	 * POST /api/orders 의 비즈니스 트랜잭션 (01 §3.1 [3]~[8]).
26	 * 락 순서: 상품(id 오름차순) → 쿠폰. 어떤 예외든 전체 롤백 = 예약·쿠폰 사용 전무.
27	 */
28	@Service
29	public class OrderCreationService {
30	
31	    private final ProductRepository productRepository;
32	    private final CouponRepository couponRepository;
33	    private final OrderRepository orderRepository;
34	    private final IdempotencyStore idempotencyStore;
35	    private final OrderPaymentProperties paymentProperties;
36	    private final ObjectMapper objectMapper;
37	    private final Clock clock;
38	
39	    public OrderCreationService(ProductRepository productRepository, CouponRepository couponRepository,
40	                                OrderRepository orderRepository, IdempotencyStore idempotencyStore,
41	                                OrderPaymentProperties paymentProperties, ObjectMapper objectMapper, Clock clock) {
42	        this.productRepository = productRepository;
43	        this.couponRepository = couponRepository;
44	        this.orderRepository = orderRepository;
45	        this.idempotencyStore = idempotencyStore;
46	        this.paymentProperties = paymentProperties;
47	        this.objectMapper = objectMapper;
48	        this.clock = clock;
49	    }
50	
51	    @Transactional
52	    public ApiResult create(String userId, OrderCreateRequest req, long idempotencyRecordId) {
53	        List<OrderCreateRequest.Item> reqItems = req.items();
54	
55	        // [3] 상품 행 잠금 (id 오름차순)
56	        List<Long> sortedIds = reqItems.stream().map(OrderCreateRequest.Item::productId).sorted().toList();
57	        Map<Long, Product> products = productRepository.lockAllByIdIn(sortedIds).stream()
58	                .collect(Collectors.toMap(Product::getId, p -> p));
59	        for (OrderCreateRequest.Item item : reqItems) {
60	            if (!products.containsKey(item.productId())) {
61	                throw new ApiException(ErrorCode.PRODUCT_NOT_FOUND, "Product " + item.productId() + " not found.");
62	            }
63	        }
64	
65	        // [4] 쿠폰 행 잠금
66	        Coupon coupon = null;
67	        if (req.couponCode() != null) {
68	            coupon = couponRepository.lockByCode(req.couponCode()).orElseThrow(() ->
69	                    new ApiException(ErrorCode.COUPON_NOT_FOUND, "Coupon " + req.couponCode() + " not found."));
70	        }
71	        Instant now = Times.now(clock);
72	
73	        // [5] 재고 (요청 순서대로 첫 부족 항목)
74	        for (OrderCreateRequest.Item item : reqItems) {
75	            Product p = products.get(item.productId());
76	            if (p.available() < item.quantity()) {
77	                throw new ApiException(ErrorCode.INSUFFICIENT_STOCK, "Product " + p.getId()
78	                        + " has only " + p.available() + " available, requested " + item.quantity() + ".");
79	            }
80	        }
81	
82	        // [6] 금액 · 쿠폰 조건 (기간 → 최소금액 → 동일 사용자 사용 중 → 소진)
83	        long subtotal = 0;
84	        for (OrderCreateRequest.Item item : reqItems) {
85	            subtotal += products.get(item.productId()).getPrice() * item.quantity();
86	        }
87	        long discount = 0;
88	        if (coupon != null) {
89	            if (!coupon.isValidAt(now)) {
90	                throw notApplicable("Coupon is outside its valid period.");
91	            }
92	            if (subtotal < coupon.getMinOrderAmount()) {
93	                throw notApplicable("Order subtotal is below the coupon's minimum order amount.");
94	            }
95	            if (orderRepository.existsByUserIdAndCouponIdAndStatusIn(userId, coupon.getId(),
96	                    OrderStatus.COUPON_IN_USE)) {
97	                throw notApplicable("The user already has an active order using this coupon.");
98	            }
99	            if (coupon.isExhausted()) {
100	                throw new ApiException(ErrorCode.COUPON_EXHAUSTED, "Coupon has no remaining quantity.");
101	            }
102	            discount = DiscountCalculator.discount(coupon.getType(), coupon.getValue(),
103	                    coupon.getMaxDiscountAmount(), subtotal);
104	        }
105	
106	        // [7] 적용
107	        OrderEntity order = new OrderEntity(userId,
108	                coupon == null ? null : coupon.getId(),
109	                coupon == null ? null : coupon.getCode(),
110	                subtotal, discount, now, now.plus(paymentProperties.ttl()));
111	        int lineNo = 0;
112	        for (OrderCreateRequest.Item item : reqItems) {
113	            order.addItem(item.productId(), item.quantity(), products.get(item.productId()).getPrice(), lineNo++);
114	        }
115	        try {
116	            order = orderRepository.saveAndFlush(order);
117	        } catch (DataIntegrityViolationException e) {
118	            String msg = String.valueOf(e.getMostSpecificCause().getMessage());
119	            if (msg.contains("uk_orders_user_coupon_in_use")) {
120	                throw notApplicable("The user already has an active order using this coupon.");
121	            }
122	            throw e;
123	        }
124	        for (OrderCreateRequest.Item item : reqItems) {
125	            products.get(item.productId()).reserve(item.quantity());
126	        }
127	        if (coupon != null) {
128	            coupon.use();
129	        }
130	
131	        // [8] 응답 직렬화 + 멱등 완료 기록 (같은 트랜잭션)
132	        OrderResponse response = OrderResponse.from(order);
133	        String body;
134	        try {
135	            body = objectMapper.writeValueAsString(response);
136	        } catch (JsonProcessingException e) {
137	            throw new IllegalStateException(e);
138	        }
139	        String location = "/api/orders/" + order.getId();
140	        idempotencyStore.complete(idempotencyRecordId, 201, body, location);
141	        return new ApiResult(201, body, location);
142	    }
143	
144	    private static ApiException notApplicable(String detail) {
145	        return new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, detail);
146	    }
147	}
