1	package com.example.order.idempotency;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ApiResult;
5	import com.example.order.common.ErrorCode;
6	import java.nio.charset.StandardCharsets;
7	import java.security.MessageDigest;
8	import java.security.NoSuchAlgorithmException;
9	import java.util.HexFormat;
10	import java.util.Objects;
11	import java.util.Optional;
12	import java.util.function.LongFunction;
13	import org.slf4j.Logger;
14	import org.slf4j.LoggerFactory;
15	import org.springframework.stereotype.Component;
16	
17	/**
18	 * 멱등성 파사드 (R4). 트랜잭션에 속하지 않는다 — 커넥션을 중첩 점유하지 않기 위함.
19	 * claim → (처리: 2xx 면 action 내부 트랜잭션에서 complete) / 오류면 claim 해제.
20	 */
21	@Component
22	public class IdempotencyFacade {
23	
24	    private static final Logger log = LoggerFactory.getLogger(IdempotencyFacade.class);
25	    private static final int MAX_CLAIM_ATTEMPTS = 3;
26	
27	    private final IdempotencyStore store;
28	
29	    public IdempotencyFacade(IdempotencyStore store) {
30	        this.store = store;
31	    }
32	
33	    /**
34	     * @param action claim 된 레코드 id 를 받아 처리하고, 자신의 트랜잭션 안에서 {@link IdempotencyStore#complete} 를 호출한 뒤
35	     *               ApiResult 를 돌려준다. 어떤 예외든 던지면 키가 해제된다.
36	     */
37	    public ApiResult execute(IdempotencyScope scope, String key, String userId, String path,
38	                             String normalizedBody, LongFunction<ApiResult> action) {
39	        String hash = sha256Hex(normalizedBody);
40	        for (int attempt = 0; attempt < MAX_CLAIM_ATTEMPTS; attempt++) {
41	            Optional<Long> claimed = store.claim(scope, key, userId, path, hash);
42	            if (claimed.isPresent()) {
43	                long id = claimed.get();
44	                try {
45	                    return action.apply(id);
46	                } catch (RuntimeException | Error e) {
47	                    releaseQuietly(id);
48	                    throw e;
49	                }
50	            }
51	            Optional<IdempotencyRecord> existing = store.find(scope, key);
52	            if (existing.isEmpty()) {
53	                continue; // 소유자가 해제함 → 재선점 시도
54	            }
55	            IdempotencyRecord r = existing.get();
56	            if (!Objects.equals(r.userId(), userId) || !r.requestPath().equals(path) || !r.bodyHash().equals(hash)) {
57	                throw new ApiException(ErrorCode.IDEMPOTENCY_KEY_MISMATCH,
58	                        "Idempotency-Key was already used with a different request.");
59	            }
60	            if (r.isCompleted()) {
61	                return new ApiResult(r.responseStatus(), r.responseBody(), r.responseLocation());
62	            }
63	            throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS,
64	                    "A request with the same Idempotency-Key is still being processed.");
65	        }
66	        throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS,
67	                "A request with the same Idempotency-Key is still being processed.");
68	    }
69	
70	    private void releaseQuietly(long id) {
71	        try {
72	            store.release(id);
73	        } catch (RuntimeException e) {
74	            log.error("Failed to release idempotency record {}", id, e);
75	        }
76	    }
77	
78	    static String sha256Hex(String s) {
79	        try {
80	            MessageDigest md = MessageDigest.getInstance("SHA-256");
81	            return HexFormat.of().formatHex(md.digest(s.getBytes(StandardCharsets.UTF_8)));
82	        } catch (NoSuchAlgorithmException e) {
83	            throw new IllegalStateException(e);
84	        }
85	    }
86	}
