1	package com.example.order.idempotency;
2	
3	import com.example.order.common.Times;
4	import java.time.Clock;
5	import java.util.Optional;
6	import org.springframework.jdbc.core.simple.JdbcClient;
7	import org.springframework.stereotype.Component;
8	import org.springframework.transaction.annotation.Propagation;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	/** idempotency_records 접근. 각 메서드의 트랜잭션 경계가 서로 다르므로 파사드와 별도 빈으로 둔다. */
12	@Component
13	public class IdempotencyStore {
14	
15	    private final JdbcClient jdbc;
16	    private final Clock clock;
17	
18	    public IdempotencyStore(JdbcClient jdbc, Clock clock) {
19	        this.jdbc = jdbc;
20	        this.clock = clock;
21	    }
22	
23	    /** 키 선점. 짧은 트랜잭션으로 즉시 커밋. 선점 성공 시 레코드 id. */
24	    @Transactional(propagation = Propagation.REQUIRES_NEW)
25	    public Optional<Long> claim(IdempotencyScope scope, String key, String userId, String path, String bodyHash) {
26	        return jdbc.sql("""
27	                        INSERT INTO idempotency_records
28	                            (scope, idem_key, user_id, request_path, body_hash, status, created_at)
29	                        VALUES (:scope, :key, :userId, :path, :hash, 'IN_PROGRESS', :now)
30	                        ON CONFLICT (scope, idem_key) DO NOTHING
31	                        RETURNING id
32	                        """)
33	                .param("scope", scope.name())
34	                .param("key", key)
35	                .param("userId", userId)
36	                .param("path", path)
37	                .param("hash", bodyHash)
38	                .param("now", Times.utc(Times.now(clock)))
39	                .query(Long.class)
40	                .optional();
41	    }
42	
43	    /** 락 없는 조회 (트랜잭션 밖). */
44	    public Optional<IdempotencyRecord> find(IdempotencyScope scope, String key) {
45	        return jdbc.sql("""
46	                        SELECT id, user_id, request_path, body_hash, status,
47	                               response_status, response_body, response_location
48	                          FROM idempotency_records WHERE scope = :scope AND idem_key = :key
49	                        """)
50	                .param("scope", scope.name())
51	                .param("key", key)
52	                .query((rs, n) -> new IdempotencyRecord(
53	                        rs.getLong("id"),
54	                        rs.getString("user_id"),
55	                        rs.getString("request_path"),
56	                        rs.getString("body_hash"),
57	                        rs.getString("status"),
58	                        (Integer) rs.getObject("response_status"),
59	                        rs.getString("response_body"),
60	                        rs.getString("response_location")))
61	                .optional();
62	    }
63	
64	    /** 비즈니스 트랜잭션 안에서 호출: 업무 변경과 완료 기록이 원자적이다. */
65	    @Transactional(propagation = Propagation.MANDATORY)
66	    public void complete(long id, int status, String body, String location) {
67	        int updated = jdbc.sql("""
68	                        UPDATE idempotency_records
69	                           SET status = 'COMPLETED', response_status = :s, response_body = :b,
70	                               response_location = :loc, completed_at = :now
71	                         WHERE id = :id AND status = 'IN_PROGRESS'
72	                        """)
73	                .param("s", status)
74	                .param("b", body)
75	                .param("loc", location)
76	                .param("now", Times.utc(Times.now(clock)))
77	                .param("id", id)
78	                .update();
79	        if (updated != 1) {
80	            throw new IllegalStateException("Idempotency record " + id + " is not in progress");
81	        }
82	    }
83	
84	    /** 오류 시 키 해제 (새 트랜잭션). */
85	    @Transactional(propagation = Propagation.REQUIRES_NEW)
86	    public void release(long id) {
87	        jdbc.sql("DELETE FROM idempotency_records WHERE id = :id AND status = 'IN_PROGRESS'")
88	                .param("id", id)
89	                .update();
90	    }
91	}
