1	package com.example.order.payment;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ApiResult;
5	import com.example.order.common.ErrorCode;
6	import com.example.order.order.OrderResponse;
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	import org.springframework.stereotype.Service;
10	
11	/**
12	 * 결제·취소 오케스트레이션. 트랜잭션을 갖지 않는다 — PG 호출은 트랜잭션·커넥션 밖.
13	 * Tx1(표식 선점) → PG → Tx2(결과 반영).
14	 */
15	@Service
16	public class OrderPaymentService {
17	
18	    private static final Logger log = LoggerFactory.getLogger(OrderPaymentService.class);
19	
20	    private final OrderPaymentTx tx;
21	    private final PaymentGatewayClient gateway;
22	
23	    public OrderPaymentService(OrderPaymentTx tx, PaymentGatewayClient gateway) {
24	        this.tx = tx;
25	        this.gateway = gateway;
26	    }
27	
28	    public ApiResult pay(long orderId, String cardToken, String idempotencyKey, long idempotencyRecordId) {
29	        OrderPaymentTx.PayBegin begin = tx.beginPay(orderId, idempotencyRecordId);
30	        if (begin instanceof OrderPaymentTx.PayBegin.Done done) {
31	            return done.result();
32	        }
33	        if (begin instanceof OrderPaymentTx.PayBegin.Expired) {
34	            throw new ApiException(ErrorCode.INVALID_STATE, "Order payment window has expired.");
35	        }
36	        long amount = ((OrderPaymentTx.PayBegin.Proceed) begin).amount();
37	
38	        PgResult pg;
39	        try {
40	            pg = gateway.pay(orderId, amount, cardToken, idempotencyKey);
41	        } catch (RuntimeException e) {
42	            pg = PgResult.unavailable();
43	        }
44	        OrderPaymentTx.PayFinish finish;
45	        try {
46	            finish = tx.finishPay(orderId, pg, idempotencyRecordId);
47	        } catch (RuntimeException e) {
48	            clearMarkerQuietly(orderId);
49	            throw e;
50	        }
51	        return switch (finish.kind()) {
52	            case APPROVED -> finish.result();
53	            case DECLINED -> throw new ApiException(ErrorCode.PAYMENT_DECLINED, "The payment was declined.");
54	            case UNAVAILABLE -> throw unavailable();
55	        };
56	    }
57	
58	    public OrderResponse cancel(long orderId) {
59	        OrderPaymentTx.CancelBegin begin = tx.beginCancel(orderId);
60	        if (begin instanceof OrderPaymentTx.CancelBegin.Done done) {
61	            return done.response();
62	        }
63	        if (begin instanceof OrderPaymentTx.CancelBegin.Expired) {
64	            throw new ApiException(ErrorCode.INVALID_STATE, "Order payment window has expired.");
65	        }
66	        String paymentId = ((OrderPaymentTx.CancelBegin.Proceed) begin).paymentId();
67	
68	        boolean refunded;
69	        try {
70	            refunded = gateway.refund(paymentId);
71	        } catch (RuntimeException e) {
72	            refunded = false;
73	        }
74	        OrderResponse response;
75	        try {
76	            response = tx.finishRefund(orderId, refunded);
77	        } catch (RuntimeException e) {
78	            clearMarkerQuietly(orderId);
79	            throw e;
80	        }
81	        if (response == null) {
82	            throw unavailable();
83	        }
84	        return response;
85	    }
86	
87	    private static ApiException unavailable() {
88	        return new ApiException(ErrorCode.PAYMENT_GATEWAY_UNAVAILABLE, "The payment gateway is unavailable.");
89	    }
90	
91	    private void clearMarkerQuietly(long orderId) {
92	        try {
93	            tx.clearMarker(orderId);
94	        } catch (RuntimeException e) {
95	            log.error("Failed to clear gateway marker for order {}", orderId, e);
96	        }
97	    }
98	}
