1	package com.example.order.payment;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ApiResult;
5	import com.example.order.common.ErrorCode;
6	import com.example.order.common.Times;
7	import com.example.order.idempotency.IdempotencyStore;
8	import com.example.order.order.OrderEntity;
9	import com.example.order.order.OrderOperations;
10	import com.example.order.order.OrderRepository;
11	import com.example.order.order.OrderResponse;
12	import com.example.order.order.OrderStatus;
13	import com.fasterxml.jackson.core.JsonProcessingException;
14	import com.fasterxml.jackson.databind.ObjectMapper;
15	import java.time.Clock;
16	import java.time.Instant;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.annotation.Transactional;
19	
20	/**
21	 * 결제·환불의 짧은 트랜잭션들 (PG 호출은 이 빈 밖, 트랜잭션 밖에서 일어난다).
22	 * 모든 메서드는 주문 행 FOR UPDATE 로 시작한다 (락 순서: 주문 → 상품 → 쿠폰).
23	 */
24	@Service
25	public class OrderPaymentTx {
26	
27	    public sealed interface PayBegin permits PayBegin.Done, PayBegin.Expired, PayBegin.Proceed {
28	        record Done(ApiResult result) implements PayBegin { }
29	        record Expired() implements PayBegin { }
30	        record Proceed(long amount) implements PayBegin { }
31	    }
32	
33	    public sealed interface CancelBegin permits CancelBegin.Done, CancelBegin.Expired, CancelBegin.Proceed {
34	        record Done(OrderResponse response) implements CancelBegin { }
35	        record Expired() implements CancelBegin { }
36	        record Proceed(String paymentId) implements CancelBegin { }
37	    }
38	
39	    /** 결제 결과 반영 결과. 거절은 커밋이 필요하므로 예외가 아닌 값으로 돌려준다. */
40	    public record PayFinish(PgResult.Kind kind, ApiResult result) { }
41	
42	    private final OrderRepository orderRepository;
43	    private final OrderOperations operations;
44	    private final IdempotencyStore idempotencyStore;
45	    private final ObjectMapper objectMapper;
46	    private final Clock clock;
47	
48	    public OrderPaymentTx(OrderRepository orderRepository, OrderOperations operations,
49	                          IdempotencyStore idempotencyStore, ObjectMapper objectMapper, Clock clock) {
50	        this.orderRepository = orderRepository;
51	        this.operations = operations;
52	        this.idempotencyStore = idempotencyStore;
53	        this.objectMapper = objectMapper;
54	        this.clock = clock;
55	    }
56	
57	    // ---- 결제 ----
58	
59	    /** Tx1: 선점 표식 기록(또는 0원 즉시 결제 / 지연 만료). */
60	    @Transactional
61	    public PayBegin beginPay(long orderId, long idempotencyRecordId) {
62	        OrderEntity order = lock(orderId);
63	        Instant now = Times.now(clock);
64	        boolean inflight = order.hasActiveGatewayCall(now);
65	        if (order.getStatus() == OrderStatus.PENDING_PAYMENT && order.isExpiredAt(now) && !inflight) {
66	            operations.expire(order, now);
67	            return new PayBegin.Expired();
68	        }
69	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT || inflight) {
70	            throw new ApiException(ErrorCode.INVALID_STATE, inflight
71	                    ? "A payment for this order is already in progress."
72	                    : "Order is " + order.getStatus() + "; expected PENDING_PAYMENT.");
73	        }
74	        if (order.getTotalPrice() == 0) {
75	            operations.commitSale(order);
76	            order.markPaid(null, now);
77	            return new PayBegin.Done(completePaid(order, idempotencyRecordId));
78	        }
79	        order.beginGatewayCall(now);
80	        return new PayBegin.Proceed(order.getTotalPrice());
81	    }
82	
83	    /** Tx2: 표식 해제 후 PG 결과 반영. */
84	    @Transactional
85	    public PayFinish finishPay(long orderId, PgResult pg, long idempotencyRecordId) {
86	        OrderEntity order = lock(orderId);
87	        Instant now = Times.now(clock);
88	        order.clearGatewayCall();
89	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT) {
90	            throw new IllegalStateException("Order " + orderId + " left PENDING_PAYMENT during PG call: "
91	                    + order.getStatus());
92	        }
93	        switch (pg.kind()) {
94	            case APPROVED -> {
95	                operations.commitSale(order);
96	                order.markPaid(pg.paymentId(), now);
97	                return new PayFinish(PgResult.Kind.APPROVED, completePaid(order, idempotencyRecordId));
98	            }
99	            case DECLINED -> {
100	                operations.failPayment(order, now);
101	                return new PayFinish(PgResult.Kind.DECLINED, null);
102	            }
103	            default -> {
104	                return new PayFinish(PgResult.Kind.UNAVAILABLE, null);
105	            }
106	        }
107	    }
108	
109	    // ---- 취소·환불 ----
110	
111	    @Transactional
112	    public CancelBegin beginCancel(long orderId) {
113	        OrderEntity order = lock(orderId);
114	        Instant now = Times.now(clock);
115	        boolean inflight = order.hasActiveGatewayCall(now);
116	        if (order.getStatus() == OrderStatus.PENDING_PAYMENT && order.isExpiredAt(now) && !inflight) {
117	            operations.expire(order, now);
118	            return new CancelBegin.Expired();
119	        }
120	        if (inflight) {
121	            throw new ApiException(ErrorCode.INVALID_STATE, "A payment operation for this order is in progress.");
122	        }
123	        switch (order.getStatus()) {
124	            case PENDING_PAYMENT -> {
125	                operations.cancelPending(order, now);
126	                return new CancelBegin.Done(OrderResponse.from(order));
127	            }
128	            case PAID -> {
129	                if (order.getPaymentId() == null) { // 0원 주문: PG 기록 없음
130	                    operations.refund(order, now);
131	                    return new CancelBegin.Done(OrderResponse.from(order));
132	                }
133	                order.beginGatewayCall(now);
134	                return new CancelBegin.Proceed(order.getPaymentId());
135	            }
136	            default -> throw new ApiException(ErrorCode.INVALID_STATE,
137	                    "Order is " + order.getStatus() + " and cannot be cancelled.");
138	        }
139	    }
140	
141	    /** @return 환불 성공 시 주문 응답, 실패(장애) 시 null — 이때 상태는 불변. */
142	    @Transactional
143	    public OrderResponse finishRefund(long orderId, boolean refunded) {
144	        OrderEntity order = lock(orderId);
145	        Instant now = Times.now(clock);
146	        order.clearGatewayCall();
147	        if (order.getStatus() != OrderStatus.PAID) {
148	            throw new IllegalStateException("Order " + orderId + " left PAID during PG refund: " + order.getStatus());
149	        }
150	        if (!refunded) {
151	            return null;
152	        }
153	        operations.refund(order, now);
154	        return OrderResponse.from(order);
155	    }
156	
157	    /** PG 호출 후 반영 트랜잭션이 실패했을 때 표식만 해제하는 보정. */
158	    @Transactional
159	    public void clearMarker(long orderId) {
160	        orderRepository.lockById(orderId).ifPresent(OrderEntity::clearGatewayCall);
161	    }
162	
163	    private OrderEntity lock(long orderId) {
164	        return orderRepository.lockById(orderId).orElseThrow(() ->
165	                new ApiException(ErrorCode.ORDER_NOT_FOUND, "Order " + orderId + " not found."));
166	    }
167	
168	    private ApiResult completePaid(OrderEntity order, long idempotencyRecordId) {
169	        String body;
170	        try {
171	            body = objectMapper.writeValueAsString(OrderResponse.from(order));
172	        } catch (JsonProcessingException e) {
173	            throw new IllegalStateException(e);
174	        }
175	        idempotencyStore.complete(idempotencyRecordId, 200, body, null);
176	        return new ApiResult(200, body, null);
177	    }
178	}
