1	package com.example.order.payment;
2	
3	import com.fasterxml.jackson.databind.JsonNode;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import java.net.URI;
6	import java.net.URLEncoder;
7	import java.net.http.HttpClient;
8	import java.net.http.HttpRequest;
9	import java.net.http.HttpResponse;
10	import java.nio.charset.StandardCharsets;
11	import java.time.Duration;
12	import java.util.LinkedHashMap;
13	import java.util.Map;
14	import java.util.concurrent.CompletableFuture;
15	import java.util.concurrent.ExecutionException;
16	import java.util.concurrent.TimeUnit;
17	import java.util.concurrent.TimeoutException;
18	import org.slf4j.Logger;
19	import org.slf4j.LoggerFactory;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * 외부 PG 클라이언트 (JDK HttpClient). 트랜잭션·DB 커넥션 밖에서 호출해야 한다.
24	 * 연결+응답 전체에 2초 데드라인. 5xx·연결 실패·타임아웃·계약 외 응답은 모두 UNAVAILABLE.
25	 * cardToken 은 로그에 남기지 않는다.
26	 */
27	@Component
28	public class PaymentGatewayClient {
29	
30	    private static final Logger log = LoggerFactory.getLogger(PaymentGatewayClient.class);
31	
32	    private final HttpClient httpClient;
33	    private final ObjectMapper objectMapper;
34	    private final String baseUrl;
35	    private final Duration timeout;
36	
37	    public PaymentGatewayClient(PaymentGatewayProperties properties, ObjectMapper objectMapper) {
38	        this.objectMapper = objectMapper;
39	        String url = properties.url();
40	        this.baseUrl = url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
41	        this.timeout = properties.timeout();
42	        this.httpClient = HttpClient.newBuilder()
43	                .version(HttpClient.Version.HTTP_1_1)
44	                .connectTimeout(timeout)
45	                .build();
46	    }
47	
48	    public PgResult pay(long orderId, long amount, String cardToken, String idempotencyKey) {
49	        try {
50	            Map<String, Object> payload = new LinkedHashMap<>();
51	            payload.put("orderId", orderId);
52	            payload.put("amount", amount);
53	            payload.put("cardToken", cardToken);
54	            HttpRequest request = HttpRequest.newBuilder(URI.create(baseUrl + "/v1/payments"))
55	                    .timeout(timeout)
56	                    .header("Content-Type", "application/json")
57	                    .header("Accept", "application/json")
58	                    .header("Idempotency-Key", idempotencyKey)
59	                    .POST(HttpRequest.BodyPublishers.ofString(objectMapper.writeValueAsString(payload),
60	                            StandardCharsets.UTF_8))
61	                    .build();
62	            HttpResponse<String> response = send(request);
63	            if (response == null || response.statusCode() != 200) {
64	                log.warn("PG payment call for order {} failed: status={}", orderId,
65	                        response == null ? "none" : response.statusCode());
66	                return PgResult.unavailable();
67	            }
68	            JsonNode node = objectMapper.readTree(response.body());
69	            String status = node.path("status").asText("");
70	            if ("APPROVED".equals(status)) {
71	                JsonNode paymentId = node.get("paymentId");
72	                if (paymentId == null || paymentId.isNull() || paymentId.asText().isBlank()) {
73	                    return PgResult.unavailable();
74	                }
75	                return PgResult.approved(paymentId.asText());
76	            }
77	            if ("DECLINED".equals(status)) {
78	                return PgResult.declined();
79	            }
80	            return PgResult.unavailable();
81	        } catch (Exception e) {
82	            log.warn("PG payment call for order {} failed: {}", orderId, e.toString());
83	            return PgResult.unavailable();
84	        }
85	    }
86	
87	    /** @return 환불 성공 여부. 장애·계약 외 응답은 false. */
88	    public boolean refund(String paymentId) {
89	        try {
90	            String encoded = URLEncoder.encode(paymentId, StandardCharsets.UTF_8).replace("+", "%20");
91	            HttpRequest request = HttpRequest.newBuilder(
92	                            URI.create(baseUrl + "/v1/payments/" + encoded + "/refund"))
93	                    .timeout(timeout)
94	                    .header("Accept", "application/json")
95	                    .POST(HttpRequest.BodyPublishers.noBody())
96	                    .build();
97	            HttpResponse<String> response = send(request);
98	            if (response == null || response.statusCode() != 200) {
99	                log.warn("PG refund call failed: status={}", response == null ? "none" : response.statusCode());
100	                return false;
101	            }
102	            return "REFUNDED".equals(objectMapper.readTree(response.body()).path("status").asText(""));
103	        } catch (Exception e) {
104	            log.warn("PG refund call failed: {}", e.toString());
105	            return false;
106	        }
107	    }
108	
109	    /** 전체 데드라인 내에 응답을 받지 못하면 null. */
110	    private HttpResponse<String> send(HttpRequest request) {
111	        CompletableFuture<HttpResponse<String>> future =
112	                httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
113	        try {
114	            return future.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
115	        } catch (TimeoutException e) {
116	            future.cancel(true);
117	            return null;
118	        } catch (ExecutionException e) {
119	            future.cancel(true);
120	            return null;
121	        } catch (InterruptedException e) {
122	            future.cancel(true);
123	            Thread.currentThread().interrupt();
124	            return null;
125	        }
126	    }
127	}
