1	package com.example.order.order;
2	
3	import com.example.order.coupon.Coupon;
4	import com.example.order.coupon.CouponRepository;
5	import com.example.order.product.Product;
6	import com.example.order.product.ProductRepository;
7	import java.time.Instant;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.function.BiConsumer;
11	import java.util.stream.Collectors;
12	import org.springframework.stereotype.Component;
13	import org.springframework.transaction.annotation.Propagation;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	/**
17	 * 호출자 트랜잭션 안에서 상품·쿠폰 수량을 변경하는 공통 로직 (MANDATORY).
18	 * 락 순서 규칙: 주문(호출자가 이미 잠금) → 상품(id 오름차순) → 쿠폰.
19	 */
20	@Component
21	@Transactional(propagation = Propagation.MANDATORY)
22	public class OrderOperations {
23	
24	    private final ProductRepository productRepository;
25	    private final CouponRepository couponRepository;
26	
27	    public OrderOperations(ProductRepository productRepository, CouponRepository couponRepository) {
28	        this.productRepository = productRepository;
29	        this.couponRepository = couponRepository;
30	    }
31	
32	    /** PENDING_PAYMENT → EXPIRED. 예약·쿠폰 복원. */
33	    public void expire(OrderEntity order, Instant now) {
34	        applyToProducts(order, (p, q) -> p.release(q));
35	        restoreCoupon(order);
36	        order.changeStatus(OrderStatus.EXPIRED, now);
37	    }
38	
39	    /** PENDING_PAYMENT → CANCELLED. */
40	    public void cancelPending(OrderEntity order, Instant now) {
41	        applyToProducts(order, (p, q) -> p.release(q));
42	        restoreCoupon(order);
43	        order.changeStatus(OrderStatus.CANCELLED, now);
44	    }
45	
46	    /** PENDING_PAYMENT → PAYMENT_FAILED. */
47	    public void failPayment(OrderEntity order, Instant now) {
48	        applyToProducts(order, (p, q) -> p.release(q));
49	        restoreCoupon(order);
50	        order.changeStatus(OrderStatus.PAYMENT_FAILED, now);
51	    }
52	
53	    /** 결제 승인: stock, reserved 각각 −q. 상태 전이는 호출자가 markPaid 로. */
54	    public void commitSale(OrderEntity order) {
55	        applyToProducts(order, (p, q) -> p.commitSale(q));
56	    }
57	
58	    /** PAID → REFUNDED: stock +q, 쿠폰 복원 (reserved 불변). */
59	    public void refund(OrderEntity order, Instant now) {
60	        applyToProducts(order, (p, q) -> p.restock(q));
61	        restoreCoupon(order);
62	        order.changeStatus(OrderStatus.REFUNDED, now);
63	    }
64	
65	    private void applyToProducts(OrderEntity order, BiConsumer<Product, Integer> action) {
66	        List<Long> ids = order.getItems().stream().map(OrderItem::getProductId).sorted().toList();
67	        Map<Long, Product> products = productRepository.lockAllByIdIn(ids).stream()
68	                .collect(Collectors.toMap(Product::getId, p -> p));
69	        for (OrderItem item : order.getItems()) {
70	            action.accept(products.get(item.getProductId()), item.getQuantity());
71	        }
72	    }
73	
74	    private void restoreCoupon(OrderEntity order) {
75	        if (order.getCouponId() == null) {
76	            return;
77	        }
78	        Coupon coupon = couponRepository.lockById(order.getCouponId()).orElseThrow();
79	        coupon.restore();
80	    }
81	}
