7	
8	/**
9	 * 주문 조회 파사드. 트랜잭션을 갖지 않는다.
10	 * 단건 조회는 만료 지연 평가를 수행한다(스케줄러 지연과 무관하게 정확성 보장).
11	 */
12	@Service
13	public class OrderQueryService {
14	
15	    private final OrderReader reader;
16	    private final OrderExpiryService expiryService;
17	    private final Clock clock;
18	
19	    public OrderQueryService(OrderReader reader, OrderExpiryService expiryService, Clock clock) {
20	        this.reader = reader;
21	        this.expiryService = expiryService;
22	        this.clock = clock;
23	    }
24	
25	    public OrderResponse get(Long id) {
26	        OrderResponse response = reader.get(id);
27	        if (response.status() == OrderStatus.PENDING_PAYMENT
28	                && !response.expiresAt().toInstant().isAfter(Times.now(clock))) {
29	            expiryService.expireOne(id); // 결제 진행 중이면 no-op
30	            return reader.get(id);
31	        }
32	        return response;
33	    }
34	
35	    public OrderPage list(String userId, String status, Integer size, String cursor) {
36	        if (userId != null && userId.isBlank()) {
37	            throw ApiException.validation("userId must not be blank.");
38	        }
39	        OrderStatus parsedStatus = null;
40	        if (status != null) {
41	            try {
42	                parsedStatus = OrderStatus.valueOf(status);
43	            } catch (IllegalArgumentException e) {
44	                throw ApiException.validation("status is not a valid order status.");
45	            }
46	        }
47	        int pageSize = size == null ? 20 : size;
48	        if (pageSize < 1 || pageSize > 100) {
49	            throw ApiException.validation("size must be between 1 and 100.");
50	        }
51	        OrderCursor parsedCursor = cursor == null ? null : OrderCursor.decode(cursor);
52	        return reader.list(userId, parsedStatus, pageSize, parsedCursor);
53	    }
