1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import java.nio.charset.StandardCharsets;
5	import java.time.Instant;
6	import java.util.Base64;
7	import java.util.regex.Pattern;
8	
9	/** keyset 커서: base64url(무패딩)("v1|" + createdAtEpochMicros + "|" + id). */
10	public record OrderCursor(Instant createdAt, long id) {
11	
12	    private static final Pattern FORMAT = Pattern.compile("^v1\\|(\\d{1,18})\\|(\\d{1,18})$");
13	    private static final int MAX_LENGTH = 200;
14	
15	    public String encode() {
16	        long micros = Math.addExact(Math.multiplyExact(createdAt.getEpochSecond(), 1_000_000L), createdAt.getNano() / 1000);
17	        String raw = "v1|" + micros + "|" + id;
18	        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
19	    }
20	
21	    public static OrderCursor decode(String cursor) {
22	        if (cursor == null || cursor.isEmpty() || cursor.length() > MAX_LENGTH) {
23	            throw invalid();
24	        }
25	        String raw;
26	        try {
27	            raw = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
28	        } catch (IllegalArgumentException e) {
29	            throw invalid();
30	        }
31	        var m = FORMAT.matcher(raw);
32	        if (!m.matches()) {
33	            throw invalid();
34	        }
35	        long micros = Long.parseLong(m.group(1));
36	        long id = Long.parseLong(m.group(2));
37	        Instant createdAt = Instant.ofEpochSecond(Math.floorDiv(micros, 1_000_000L),
38	                Math.floorMod(micros, 1_000_000L) * 1000L);
39	        return new OrderCursor(createdAt, id);
40	    }
41	
42	    private static ApiException invalid() {
43	        return ApiException.validation("cursor is invalid.");
44	    }
45	}
