1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import jakarta.persistence.EntityManager;
6	import jakarta.persistence.TypedQuery;
7	import java.util.List;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	/** 읽기 전용 트랜잭션 조회. */
12	@Service
13	public class OrderReader {
14	
15	    private final OrderRepository orderRepository;
16	    private final EntityManager entityManager;
17	
18	    public OrderReader(OrderRepository orderRepository, EntityManager entityManager) {
19	        this.orderRepository = orderRepository;
20	        this.entityManager = entityManager;
21	    }
22	
23	    @Transactional(readOnly = true)
24	    public OrderResponse get(Long id) {
25	        return orderRepository.findById(id)
26	                .map(OrderResponse::from)
27	                .orElseThrow(() -> notFound(id));
28	    }
29	
30	    /** 필터는 조건부 조합(null 바인딩 타입 추론 문제 회피). 정렬 created_at DESC, id DESC. */
31	    @Transactional(readOnly = true)
32	    public OrderPage list(String userId, OrderStatus status, int size, OrderCursor cursor) {
33	        StringBuilder jpql = new StringBuilder("select o from OrderEntity o where 1 = 1");
34	        if (userId != null) {
35	            jpql.append(" and o.userId = :userId");
36	        }
37	        if (status != null) {
38	            jpql.append(" and o.status = :status");
39	        }
40	        if (cursor != null) {
41	            jpql.append(" and (o.createdAt < :cAt or (o.createdAt = :cAt and o.id < :cId))");
42	        }
43	        jpql.append(" order by o.createdAt desc, o.id desc");
44	        TypedQuery<OrderEntity> q = entityManager.createQuery(jpql.toString(), OrderEntity.class);
45	        if (userId != null) {
46	            q.setParameter("userId", userId);
47	        }
48	        if (status != null) {
49	            q.setParameter("status", status);
50	        }
51	        if (cursor != null) {
52	            q.setParameter("cAt", cursor.createdAt());
53	            q.setParameter("cId", cursor.id());
54	        }
55	        q.setMaxResults(size + 1);
56	        List<OrderEntity> rows = q.getResultList();
57	        boolean hasNext = rows.size() > size;
58	        List<OrderEntity> page = hasNext ? rows.subList(0, size) : rows;
59	        String next = null;
60	        if (hasNext) {
61	            OrderEntity last = page.get(page.size() - 1);
62	            next = new OrderCursor(last.getCreatedAt(), last.getId()).encode();
63	        }
64	        return new OrderPage(page.stream().map(OrderResponse::from).toList(), next);
65	    }
66	
67	    static ApiException notFound(Long id) {
68	        return new ApiException(ErrorCode.ORDER_NOT_FOUND, "Order " + id + " not found.");
69	    }
70	}
