1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import com.example.order.common.Times;
6	import java.time.Clock;
7	import java.time.Instant;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	/** 배송 상태 전이 (R8). 재고·쿠폰 변화 없음. */
12	@Service
13	public class OrderTransitionService {
14	
15	    private final OrderRepository orderRepository;
16	    private final Clock clock;
17	
18	    public OrderTransitionService(OrderRepository orderRepository, Clock clock) {
19	        this.orderRepository = orderRepository;
20	        this.clock = clock;
21	    }
22	
23	    @Transactional
24	    public OrderResponse ship(Long id) {
25	        return transition(id, OrderStatus.PAID, OrderStatus.SHIPPED);
26	    }
27	
28	    @Transactional
29	    public OrderResponse deliver(Long id) {
30	        return transition(id, OrderStatus.SHIPPED, OrderStatus.DELIVERED);
31	    }
32	
33	    private OrderResponse transition(Long id, OrderStatus from, OrderStatus to) {
34	        OrderEntity order = orderRepository.lockById(id).orElseThrow(() -> OrderReader.notFound(id));
35	        Instant now = Times.now(clock);
36	        if (order.hasActiveGatewayCall(now) || order.getStatus() != from) {
37	            throw new ApiException(ErrorCode.INVALID_STATE,
38	                    "Order is " + order.getStatus() + "; expected " + from + ".");
39	        }
40	        order.changeStatus(to, now);
41	        return OrderResponse.from(order);
42	    }
43	}
