22	        this.clock = clock;
23	    }
24	
25	    @Transactional(readOnly = true)
26	    public List<Long> findExpiredIds(int limit) {
27	        Instant now = Times.now(clock);
28	        return orderRepository.findExpiredIds(now, now.minus(OrderEntity.GATEWAY_INFLIGHT_TTL), PageRequest.of(0, limit));
29	    }
30	
31	    /** 주문 락 후 상태·만료·표식을 재확인하고 만료시킨다. @return 실제로 만료시켰는가 */
32	    @Transactional
33	    public boolean expireOne(Long orderId) {
34	        OrderEntity order = orderRepository.lockById(orderId).orElse(null);
35	        if (order == null) {
36	            return false;
37	        }
38	        Instant now = Times.now(clock);
39	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT
40	                || !order.isExpiredAt(now)
41	                || order.hasActiveGatewayCall(now)) {
42	            return false;
43	        }
44	        operations.expire(order, now);
45	        return true;
46	    }
47	}
