1	package com.example.order.order;
2	
3	import java.util.List;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.scheduling.annotation.Scheduled;
7	import org.springframework.stereotype.Component;
8	
9	/** 500ms 고정 지연 스캔. 만료 후 2초 안에 EXPIRED 가 반영되도록 한다 (R6.2). */
10	@Component
11	public class ExpirationScheduler {
12	
13	    private static final Logger log = LoggerFactory.getLogger(ExpirationScheduler.class);
14	    private static final int BATCH = 100;
15	    private static final int MAX_BATCHES_PER_TICK = 10;
16	
17	    private final OrderExpiryService expiryService;
18	
19	    public ExpirationScheduler(OrderExpiryService expiryService) {
20	        this.expiryService = expiryService;
21	    }
22	
23	    @Scheduled(fixedDelayString = "${order.expiry.scan-interval:PT0.5S}")
24	    public void scan() {
25	        try {
26	            for (int i = 0; i < MAX_BATCHES_PER_TICK; i++) {
27	                List<Long> ids = expiryService.findExpiredIds(BATCH);
28	                if (ids.isEmpty()) {
29	                    return;
30	                }
31	                boolean progressed = false;
32	                for (Long id : ids) {
33	                    try {
34	                        progressed |= expiryService.expireOne(id);
35	                    } catch (RuntimeException e) {
36	                        log.error("Failed to expire order {}", id, e);
37	                    }
38	                }
39	                if (!progressed || ids.size() < BATCH) {
40	                    return;
41	                }
42	            }
43	        } catch (RuntimeException e) {
44	            log.error("Expiration scan failed", e);
45	        }
46	    }
47	}
