45	    @FunctionalInterface
46	    public interface Handler {
47	        Response handle(Recorded request);
48	    }
49	
50	    private final HttpServer server;
51	    private final List<Recorded> requests = new CopyOnWriteArrayList<>();
52	    private final Map<String, String> paymentsByKey = new ConcurrentHashMap<>();
53	    private final AtomicInteger sequence = new AtomicInteger();
54	    private volatile Handler handler = this::defaultHandler;
55	
56	    public FakePaymentGateway() {
57	        try {
58	            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
59	        } catch (IOException e) {
60	            throw new IllegalStateException(e);
61	        }
62	        server.setExecutor(Executors.newCachedThreadPool());
63	        server.createContext("/", this::serve);
64	        server.start();
65	    }
66	
67	    public String baseUrl() {
68	        return "http://127.0.0.1:" + server.getAddress().getPort();
69	    }
70	
71	    public void respondWith(Handler handler) {
72	        this.handler = handler;
73	    }
74	
75	    /** 기록·멱등 상태·핸들러를 초기화한다 (테스트 간 격리용). */
76	    public void reset() {
77	        requests.clear();
78	        paymentsByKey.clear();
79	        handler = this::defaultHandler;
80	    }
81	
82	    public List<Recorded> requests() {
83	        return new ArrayList<>(requests);
84	    }
85	
86	    public List<Recorded> requestsTo(String pathPrefix) {
87	        return requests.stream().filter(r -> r.path().startsWith(pathPrefix)).toList();
88	    }
89	
90	    public void stop() {
91	        server.stop(0);
92	    }
93	
94	    private Response defaultHandler(Recorded r) {
95	        if (r.path().equals("/v1/payments")) {
96	            String key = r.header("Idempotency-Key");
97	            String json = paymentsByKey.computeIfAbsent(String.valueOf(key), k -> {
98	                boolean decline = r.body().contains("\"cardToken\":\"decline");
99	                return decline
100	                        ? "{\"paymentId\":\"pay-" + sequence.incrementAndGet() + "\",\"status\":\"DECLINED\"}"
101	                        : "{\"paymentId\":\"pay-" + sequence.incrementAndGet() + "\",\"status\":\"APPROVED\"}";
102	            });
103	            return Response.json(json);
104	        }
105	        if (r.path().matches("/v1/payments/[^/]+/refund")) {
106	            String paymentId = r.path().split("/")[3];
107	            return Response.json("{\"paymentId\":\"" + paymentId + "\",\"status\":\"REFUNDED\"}");
108	        }
109	        return Response.status(404);
110	    }
111	
112	    private void serve(HttpExchange exchange) throws IOException {
113	        byte[] bodyBytes = exchange.getRequestBody().readAllBytes();
114	        Map<String, String> headers = new TreeMap<>();
115	        exchange.getRequestHeaders().forEach((k, v) -> headers.put(k.toLowerCase(Locale.ROOT), v.get(0)));
116	        Recorded recorded = new Recorded(exchange.getRequestMethod(), exchange.getRequestURI().getPath(), headers,
117	                new String(bodyBytes, StandardCharsets.UTF_8));
118	        requests.add(recorded);
119	        Response response;
120	        try {
121	            response = handler.handle(recorded);
122	            if (response.delayMillis() > 0) {
123	                Thread.sleep(response.delayMillis());
124	            }
125	        } catch (InterruptedException e) {
126	            Thread.currentThread().interrupt();
127	            exchange.close();
128	            return;
129	        }
130	        byte[] out = response.body().getBytes(StandardCharsets.UTF_8);
131	        exchange.getResponseHeaders().add("Content-Type", "application/json");
132	        try {
133	            exchange.sendResponseHeaders(response.status(), out.length == 0 ? -1 : out.length);
134	            if (out.length > 0) {
135	                exchange.getResponseBody().write(out);
136	            }
137	        } catch (IOException ignored) {
138	            // 클라이언트가 타임아웃으로 먼저 끊은 경우
139	        } finally {
140	            exchange.close();
141	        }
142	    }
143	}
