        assertNoServerErrors(results);
        assertThat(count(results, 201)).isEqualTo(10);
        assertThat(count(results, 409)).isEqualTo(10);
        results.stream().filter(r -> code(r) == 409)
                .forEach(r -> assertProblem(r, 409, "INSUFFICIENT_STOCK"));
