    @RepeatedTest(value = 3, name = "R10.2 totalQuantity 5 쿠폰을 서로 다른 사용자 15명이 동시 사용 -> 201 정확히 5, 409 10, usedCount 5 ({currentRepetition}/{totalRepetitions})")
    void r10_2_couponQuantityIsNeverExceeded() {
