    void gatewayDeclineIsLastStage() {
        long orderId = newOrder(newProduct(1000, 5), 1).get("id").asLong();

        assertProblem(pay(orderId, uniqueKey(), "decline_card"), 402, "PAYMENT_DECLINED");
    }
}
